package com.wizzadrds.theworldremembers.chronicle;
import com.wizzadrds.theworldremembers.memory.*; import com.wizzadrds.theworldremembers.relationship.*; import com.wizzadrds.theworldremembers.family.*; import com.wizzadrds.theworldremembers.village.*; import net.minecraft.server.MinecraftServer; import java.util.*;
public final class ChronicleBuilder{private ChronicleBuilder(){} public static ChronicleSnapshot build(MinecraftServer s){var memories=MemoryManager.get(s).memoriesOfAll();var rel=RelationshipManager.get(s);var fam=FamilyManager.get(s);var villages=VillageManager.get(s);var vh=VillageHistoryManager.get(s);var lines=new ArrayList<String>();for(var m:memories)if(m.importance().ordinal()>=MemoryImportance.IMPORTANT.ordinal())lines.add(m.gameTime()+" | "+m.npcId()+" | "+m.summary());lines.sort(Comparator.naturalOrder());if(lines.size()>64)lines.subList(0,lines.size()-64).clear();var people=new ArrayList<String>();var seen=new LinkedHashSet<UUID>();for(var m:memories) {seen.add(m.npcId());seen.add(m.playerId());}for(var id:seen)people.add(id.toString());var relationships=new ArrayList<String>();for(var id:seen)for(var other:seen){if(id.equals(other))continue;var r=rel.get(id,other);if(r!=null)relationships.add(id+" -> "+other+" trust="+r.trust()+" fear="+r.fear()+" respect="+r.respect());}var families=new ArrayList<String>();for(var id:seen)for(var r:fam.getRelations(id))families.add(r.npcId()+" --"+r.type()+"--> "+r.relatedNpcId());var villageLines=new ArrayList<String>();for(var v:villages.all()){var h=vh.get(v.villageId());villageLines.add(v.villageId()+" population="+v.population()+" center="+v.center()+ (h==null?"":" peak="+h.peakPopulation()+" events="+h.totalImportantEvents()));}return new ChronicleSnapshot(lines,people,relationships,families,villageLines);}}
